def extract_bot():
    os.makedirs(BOT_DIR, exist_ok=True)
    marker = os.path.join(BOT_DIR, "VERSION")
    try:
        current = open(marker, encoding="utf-8").read().strip()
    except Exception:
        current = ""
    if current == VERSION and os.path.exists(os.path.join(BOT_DIR, "main.py")):
        return
    raw = base64.b64decode(PAYLOAD_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
        members = tf.getmembers()
        for m in members:
            if m.name.startswith("/") or ".." in m.name.split(os.sep):
                raise RuntimeError("Unsafe embedded bot archive path")
        tf.extractall(BOT_DIR, members=members)
    # Bot extracts a minimal version file for update detection.
    with open(marker, "w", encoding="utf-8") as f:
        f.write(VERSION)


def _spawn_bot():
    global BOT_PROCESS
    env = os.environ.copy()
    env.setdefault("BACKUP_CHAT", "-1003484913073")
    env.setdefault("BOT_NAME", "RAVAN X")
    BOT_PROCESS = subprocess.Popen([sys.executable, "main.py"], cwd=BOT_DIR, env=env)
    print("Hosting bot worker launched from embedded package", flush=True)


def _watch_bot():
    """Restart the embedded polling bot if its process exits unexpectedly."""
    delay = 3
    while not BOT_STOP.wait(5):
        if BOT_PROCESS is not None and BOT_PROCESS.poll() is None:
            delay = 3
            continue
        if not os.environ.get("BOT_TOKEN"):
            continue
        if BOT_STOP.wait(delay):
            break
        try:
            _spawn_bot()
            delay = min(delay * 2, 60)
        except Exception as exc:
            print("Bot restart failed:", type(exc).__name__, flush=True)
            delay = min(delay * 2, 60)


def discover_bot_link():
    global BOT_URL
    token = os.environ.get("BOT_TOKEN", "").strip()
    if not token:
        return
    try:
        import urllib.request
        req = urllib.request.Request(f"https://api.telegram.org/bot{token}/getMe", headers={"User-Agent":"RAVANX"})
        with urllib.request.urlopen(req, timeout=8) as response:
            payload = json.loads(response.read().decode("utf-8"))
        username = (payload.get("result") or {}).get("username")
        if payload.get("ok") and username:
            BOT_URL = "https://t.me/" + username
            print("Telegram bot link resolved from token.", flush=True)
    except Exception as exc:
        print("Bot username auto-detect failed; using configured fallback.", flush=True)


def start_bot():
    extract_bot()
    # Runtime dependency install keeps deployment to one Python file.
    req_file = os.path.join(BOT_DIR, "requirements.txt")
    if os.path.isfile(req_file):
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-r", req_file], check=True)
    if not os.environ.get("BOT_TOKEN"):
        print("ERROR: Render Environment me BOT_TOKEN set nahi hai; website chalegi, bot worker nahi.", flush=True)
        return
    discover_bot_link()
    _spawn_bot()
    threading.Thread(target=_watch_bot, daemon=True).start()


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlparse(self.path).path
        if path in ("/health", "/healthz"):
            body = json.dumps({"ok": True, "website": "up", "bot_process": bool(BOT_PROCESS and BOT_PROCESS.poll() is None)}).encode()
            self.send_response(200); self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body))); self.end_headers(); self.wfile.write(body); return
        if path in ("/bot", "/telegram"):
            self.send_response(302); self.send_header("Location", BOT_URL); self.end_headers(); return
        body = PAGE.encode("utf-8")
        self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body))); self.send_header("Cache-Control", "no-store")
        self.end_headers(); self.wfile.write(body)
    def log_message(self, fmt, *args):
        print("[RAVANX combined]", fmt % args, flush=True)


def main():
    global SERVER
    if not os.environ.get("BOT_TOKEN"):
        print("ERROR: Render Environment me BOT_TOKEN set hona chahiye; website chalegi par Telegram bot start nahi hoga.", flush=True)
    try:
        start_bot()
    except Exception as e:
        print("Bot worker failed to start:", type(e).__name__, str(e)[:160], flush=True)
    SERVER = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    def stop_handler(signum, frame):
        BOT_STOP.set()
        try:
            if BOT_PROCESS and BOT_PROCESS.poll() is None:
                BOT_PROCESS.terminate()
        except Exception:
            pass
        threading.Thread(target=SERVER.shutdown, daemon=True).start()
    signal.signal(signal.SIGTERM, stop_handler)
    signal.signal(signal.SIGINT, stop_handler)
    print(f"RAVAN X single-file website + Telegram bot ready on port {PORT}; bot URL={BOT_URL}", flush=True)
    SERVER.serve_forever()
    SERVER.server_close()


if __name__ == "__main__":
    main()
